// FUNCTION: BFME2 0x0016A850 size=415 name=?Compute_Plane_Equations@MeshGeometryClass@@MAEXPAVVector4@@@Z evidence=N:ledger tier=B hypothesis:Z
void MeshGeometryClass::Compute_Plane_Equations(Vector4 *peq)
{
	TriIndex *poly = Poly->Get_Array();
	Vector3 *vert = Vertex->Get_Array();

	for (int pidx = 0; pidx < PolyCount; pidx++) {
		Vector3 a, b, normal;
		const Vector3 &p0 = vert[poly[pidx][0]];

		Vector3::Subtract(vert[poly[pidx][1]], p0, &a);
		Vector3::Subtract(vert[poly[pidx][2]], p0, &b);
		Vector3::Cross_Product(a, b, &normal);
		normal.Normalize();

		peq[pidx].Set(normal.X, normal.Y, normal.Z, -(Vector3::Dot_Product(p0, normal)));
	}
	Set_Flag(DIRTY_PLANES, false);
}

// FUNCTION: BFME2 0x0016A9F0 size=239 name=?Compute_Bounds@MeshGeometryClass@@MAEXPAVVector3@@@Z evidence=N:ledger tier=B hypothesis:Z
void MeshGeometryClass::Compute_Bounds(Vector3 *verts)
{
	BoundBoxMin.Set(0.0f, 0.0f, 0.0f);
	BoundBoxMax.Set(0.0f, 0.0f, 0.0f);
	BoundSphereCenter.Set(0.0f, 0.0f, 0.0f);
	BoundSphereRadius = 0.0f;
	if (VertexCount != 0) {
		if (verts == NULL)
			verts = Vertex->Get_Array();
		VectorProcessorClass::MinMax(verts, BoundBoxMin, BoundBoxMax, VertexCount);
		BoundSphereCenter = (BoundBoxMin + BoundBoxMax) * 0.5f;
		Vector3 corner = BoundBoxMax - BoundSphereCenter;
		Flags &= ~DIRTY_BOUNDS;
		BoundSphereRadius = (float)sqrt(corner.Length2()) * 1.00001f;
	}
}

