	if (VertexBoneLink != NULL) size += VertexBoneLink->Get_Count() * 2;
	if (BoneLinkSpans != NULL) size += BoneLinkSpans->Get_Count() * 2;
	if (PolySurfaceType != NULL) size += PolySurfaceType->Get_Count();
