// FUNCTION: BFME2 0x0016B020 size=191 name=?read_triangles@MeshGeometryClass@@IAE_NAAVChunkLoadClass@@@Z evidence=N:ledger tier=A
bool MeshGeometryClass::read_triangles(ChunkLoadClass &cload)
{
	TriIndex *tris = Poly->Get_Array();
	Flags &= ~DIRTY_PLANES;
	Vector4 *planes = get_planes(true);
	unsigned char *surface = PolySurfaceType->Get_Array();

	W3dTriStruct rec;
	for (int i = 0; i < PolyCount; i++) {
		if (cload.Read(&rec, sizeof(W3dTriStruct)) != sizeof(W3dTriStruct))
			return false;

		tris[i].I = (unsigned short)rec.Vindex[0];
		tris[i].J = (unsigned short)rec.Vindex[1];
		tris[i].K = (unsigned short)rec.Vindex[2];
		planes[i].X = rec.Normal.X;
		planes[i].Y = rec.Normal.Y;
		planes[i].Z = rec.Normal.Z;
		planes[i].W = -rec.Dist;
		surface[i] = (unsigned char)rec.Attributes;
	}
	return true;
}

